import fs from "node:fs";
import path from "node:path";
const rows = JSON.parse(Buffer.from("", "base64").toString("utf8"));
if (rows.length !== 56) throw new Error("Unexpected row count");
const root = path.resolve(".cache/getlink-history-2026-10-04-to-10");
fs.mkdirSync(root, { recursive: true });
const fmt = new Intl.DateTimeFormat("vi-VN", { timeZone: "Asia/Saigon", dateStyle: "short", timeStyle: "medium" });
const dayFmt = new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Saigon", year: "numeric", month: "2-digit", day: "2-digit" });
const data = rows.map(row => ({ ...row, localTime: fmt.format(new Date(row.createdAt)), day: dayFmt.format(new Date(row.createdAt)) }));
const days = [...new Set(data.map(row => row.day))].sort();
const total = rows.reduce((sum, row) => sum + Number(row.creditUsed || 0), 0);
const esc = value => String(value ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const cell = value => {
 let s = String(value ?? "");
 if (/^[=+@\-\t\r]/.test(s)) s = "'" + s;
 return '"' + s.replaceAll('"', '""') + '"';
};
const csv = [["Ngay", "Thoi gian Viet Nam", "Ma model", "Ten model", "Credit"],
 ...data.map(row => [row.day, row.localTime, row.productId, row.title, row.creditUsed])].map(row => row.map(cell).join(",")).join("\r\n");
fs.writeFileSync(path.join(root, "getlink-2026-10-04-to-10.csv"), "\uFEFF" + csv);
fs.writeFileSync(path.join(root, "getlink-2026-10-04-to-10.json"), JSON.stringify({ start: "2026-10-04", end: "2026-10-10", timezone: "Asia/Saigon", source: "live-core-read-only-not-decrypted-backup", totalCredit: total, rows: data }, null, 2));
const html = `<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lịch sử Getlink 04–10/10/2026</title><style>
body{font:15px/1.6 system-ui,sans-serif;color:#17221e;background:#f5f7f6;margin:0;padding:32px}main{max-width:1300px;margin:auto}h1{font-size:26px;margin:0}p{margin:10px 0}.stats{padding:14px 0;border-block:1px solid #cbd5d0;margin:20px 0}.notice{color:#715114}nav{display:flex;gap:24px;flex-wrap:wrap;margin:18px 0}a{color:#006f4b}label{display:block;margin:20px 0}select{font:inherit;padding:6px 12px;margin-left:12px;border:1px solid #a5b7ac;background:white}.wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;background:white}th,td{border-bottom:1px solid #d6dfda;text-align:left;padding:12px;vertical-align:top}th{background:#e7eee9;font-size:13px}td:first-child{white-space:nowrap}td:nth-child(2){font:13px/1.7 ui-monospace,monospace}td:last-child{text-align:right}footer{color:#56665d;font-size:13px;margin-top:18px}[hidden]{display:none}@media(max-width:650px){body{padding:16px}h1{font-size:22px}}
</style><main><h1>Lịch sử Getlink 04–10/10/2026</h1><p>Giờ Việt Nam (UTC+7). Dữ liệu chỉ đọc từ database hiện tại; không khôi phục lên web.</p><div class="stats"><strong id="count">${rows.length}</strong> lượt · <strong id="credit">${total}</strong> Credit</div><p class="notice">Bản này có mã model, tên, giờ tải và Credit. Không có email, cookie, token đăng nhập hay link tải file. Link gốc/link đã làm sạch ngày 07/10 không còn trong database; cần giải mã backup để kiểm tra. Backup nguyên gốc bên dưới đã được kiểm tra SHA-256 nhưng chưa giải mã.</p><nav><a href="getlink-2026-10-04-to-10.csv">CSV</a><a href="getlink-2026-10-04-to-10.json">JSON</a><a href="../getlink-backup-2026-10-12/3dipl-history-export.8A9mwr/3dipl-core-20261011T180124Z.archive.gz.age">Backup Core nguyên gốc (mã hóa)</a></nav><label>Ngày<select id="day"><option value="">Tất cả</option>${days.map(day => `<option value="${esc(day)}">${esc(day)}</option>`).join("")}</select></label><div class="wrap"><table><thead><tr><th>Thời gian Việt Nam</th><th>Mã model</th><th>Tên model gốc</th><th>Credit</th></tr></thead><tbody>${data.map(row=>`<tr data-day="${esc(row.day)}" data-credit="${Number(row.creditUsed || 0)}"><td>${esc(row.localTime)}</td><td>${esc(row.productId)}</td><td>${esc(row.title)}</td><td>${esc(row.creditUsed)}</td></tr>`).join("")}</tbody></table></div><footer>Khoảng dữ liệu: từ 00:00 ngày 04/10 đến trước 00:00 ngày 11/10, Asia/Saigon. Bản backup được tạo lúc 01:01:24 ngày 12/10/2026 theo giờ Việt Nam. Đây không phải kết quả đọc nội dung backup.</footer></main><script>document.getElementById("day").addEventListener("change",function(){let n=0,c=0;document.querySelectorAll("tbody tr").forEach(row=>{row.hidden=Boolean(this.value&&row.dataset.day!==this.value);if(!row.hidden){n++;c+=Number(row.dataset.credit)}});document.getElementById("count").textContent=n;document.getElementById("credit").textContent=c;});</script></html>`;
fs.writeFileSync(path.join(root,"index.html"),html);
console.log(JSON.stringify({records:rows.length,totalCredit:total,days:Object.fromEntries(days.map(day=>[day,data.filter(row=>row.day===day).length])),root}));

